from __future__ import annotations

from datetime import datetime, timezone

from gitseed.application import execute
from gitseed.collect.search import Candidate, CollectResult
from gitseed.grade.types import GradeResult
from gitseed.pipeline.run import FetchedFiles
from gitseed.ports import RepositoryMetadata, RunPorts, RunRequest
from gitseed.scoring import ScoreInputs
from gitseed.storage import SQLiteRunStore


class Repository:
    def __init__(self, candidate: Candidate) -> None:
        self.candidate = candidate

    def search(self, query: str, limit: int) -> CollectResult:
        return CollectResult(candidates=(self.candidate,), pages_fetched=1)

    def metadata(self, candidate: Candidate, at: datetime) -> RepositoryMetadata:
        return RepositoryMetadata(ScoreInputs(True, True, True))


class Files:
    def read(self, candidate: Candidate) -> FetchedFiles:
        return FetchedFiles((("main.py", "def add(a, b):\n    return a + b\n"),))


class Model:
    def evaluate(self, digest: str) -> GradeResult:
        return GradeResult(8, 7, "fixture", "fixture", 0.0, "fixture-v1")

    def flags_malicious(self, digest: str) -> bool:
        return False


class Clock:
    def __init__(self, at: datetime) -> None:
        self.at = at

    def now(self) -> datetime:
        return self.at


def recorded_artifact(at: datetime, stars: int):
    candidate = Candidate(
        repo="org/repo",
        owner="org",
        html_url="https://github.com/org/repo",
        stars=stars,
        pushed_at="2026-07-27T00:00:00Z",
    )
    return execute(
        RunRequest("small tools", 1),
        RunPorts(Repository(candidate), Files(), Model(), Clock(at)),
    )


def test_observations_are_chronological_when_runs_are_saved_out_of_order(tmp_path) -> None:
    oldest = datetime(2026, 7, 25, 12, 0, tzinfo=timezone.utc)
    tied = datetime(2026, 7, 26, 12, 0, tzinfo=timezone.utc)
    newest = datetime(2026, 7, 27, 12, 0, tzinfo=timezone.utc)

    with SQLiteRunStore(tmp_path / "runs.db") as store:
        store.save("newest", recorded_artifact(newest, 40))
        store.save("first-at-tied-time", recorded_artifact(tied, 30))
        store.save("second-at-tied-time", recorded_artifact(tied, 31))
        store.save("oldest", recorded_artifact(oldest, 20))

        observations = store.observations()

    assert [
        (observation.run_id, observation.observed_at, observation.stars)
        for observation in observations
    ] == [
        ("oldest", oldest, 20),
        ("first-at-tied-time", tied, 30),
        ("second-at-tied-time", tied, 31),
        ("newest", newest, 40),
    ]
